const {
	getState,
	itemType,
	polySources,
	rows
} = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (itemId) => {
	if (isPolymorphic) {
		const itemTypeId = rows.get(itemId, 'itemtype');
		const name = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[name];
	}

	return itemType;
};

const state = getState();
const hidden = !state.grid.selectedRows.some((selectedRowId) =>
	getItemType(selectedRowId).is_versionable === '1'
);

return { hidden };
